def main(argv=None):
    args = build_parser().parse_args(argv)
    if args.fn not in (cmd_agent, cmd_core, cmd_awake):
        _mark_install()                 # not the copy another machine runs here
    try:
        return args.fn(args) or 0
    except (SystemExit, KeyboardInterrupt, BrokenPipeError):
        raise
    except Exception:
        import traceback
        error("UNCAUGHT " + traceback.format_exc())
        raise
    finally:
        Progress.done()                 # a --status-file outlives no command

if __name__ == "__main__":
    sys.exit(main())
